(6728338, 1005682, 118154, '<td valign="top">I know what you mean in my own way.</td>', 'I know what you mean in my own way.', '2012-04-01 09:47:42.000000', NULL, 1),
(6728473, 1006190, 134859, '<td valign="top">This is an interesting collection.  I like the fish, and the colors.  The focus is also well done.</td>', 'This is an interesting collection.  I like the fish, and the colors.  The focus is also well done.', '2012-04-01 13:01:20.000000', NULL, 1),
(6728475, 1006681, 134859, '<td valign="top">I''ve never seen anything like this.  I think that if you had shot in low lighting, to capture the essence of the candle''s glow, it would have looked really cool.  However, being said, I do not know the camera settings required to do this (as I have yet to learn this).</td>', 'I''ve never seen anything like this.  I think that if you had shot in low lighting, to capture the essence of the candle''s glow, it would have looked really cool.  However, being said, I do not know the camera settings required to do this (as I have yet to learn this).', '2012-04-01 13:02:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6728476, 1006561, 134859, '<td valign="top">Very colorful collection.  I think the focus is off.  Also, the crop seems a little tight, I would have liked to had seen the whole collection (including all of the hula hoops in the frame).</td>', 'Very colorful collection.  I think the focus is off.  Also, the crop seems a little tight, I would have liked to had seen the whole collection (including all of the hula hoops in the frame).', '2012-04-01 13:02:52.000000', NULL, 1),
