(6731270, 1006768, 114225, '<td valign="top">I''m glad (pun intended) that you chose to have the dividers cut the frame diagonally.</td>', 'I''m glad (pun intended) that you chose to have the dividers cut the frame diagonally.', '2012-04-03 14:45:07.000000', NULL, 1),
